import { CONTROL_TOKENS as T } from "./tokens.ts";

export type ControlRect = { x: number; y: number; w: number; h: number };
export type ControlViewport = {
  variant: "desktop" | "portrait" | "landscape" | "compact";
  width: number;
  height: number;
  /** Compact landscape uses the space below the reels for readouts. */
  footerWidth?: number;
};
const rect = (x: number, y: number, w: number, h: number): ControlRect => ({
  x,
  y,
  w,
  h,
});
const absent = () => rect(0, 0, 0, 0);

/** The only breakpoint definitions. No theme assets, game logic or feature state. */
export function createControlLayout(viewport: ControlViewport) {
  const { width: w, height: h, variant } = viewport;
  const { target: t, gap, moduleGap: mg } = T;
  let turbo: ControlRect,
    menu: ControlRect,
    balance: ControlRect,
    win: ControlRect,
    bet: ControlRect,
    auto: ControlRect,
    spin: ControlRect,
    buy: ControlRect,
    betButton: ControlRect,
    minus: ControlRect,
    plus: ControlRect,
    ante: ControlRect;
  if (variant === "portrait") {
    // The readouts sit above one compact play group. Spin is centered on the
    // reels; the bet well never grows to fill the space left by the actions.
    const group = Math.min(w, T.portraitGroup),
      gx = (w - group) / 2,
      rw = (group - gap) / 2,
      diameter = group < 320 ? T.narrowSpin : T.mobileSpin,
      sy = T.portraitReadout + gap,
      sx = Math.min((w - diameter) / 2, w - gx - diameter - t * 2 - gap * 2),
      bw = sx - gap - gx,
      ax = sx + diameter + gap;
    balance = rect(gx, 0, rw, T.portraitReadout);
    win = rect(gx + rw + gap, 0, rw, T.portraitReadout);
    spin = rect(sx, sy, diameter, diameter);
    bet = rect(gx, sy + (T.mobileSpin - t * 2) / 2, bw, t * 2);
    betButton = rect(0, 0, bw - t, t);
    plus = rect(bw - t, 0, t, t);
    minus = rect(bw - t, t, t, t);
    ante = rect(0, t, bw - t, t);
    auto = rect(ax, sy, t, t);
    buy = rect(ax + t + gap, sy, t, t);
    // Action pair above, separate utility pair below. Four full-size targets
    // fit beside Spin without growing the bet well or adding another row.
    turbo = rect(ax, sy + t + gap, t, t);
    menu = rect(ax + t + gap, sy + t + gap, t, t);
  } else if (variant === "landscape") {
    const left = 128,
      right = T.mobileSpin,
      rx = w - right,
      sy = (h - (t * 2 + right + gap * 2)) / 2;
    menu = rect(0, 0, t, t);
    buy = rect(left - t, 0, t, t);
    balance = rect(0, 52, left, 44);
    win = rect(0, 100, left, 44);
    bet = rect(0, 148, left, 128);
    betButton = rect(0, 0, left - t, t * 2);
    plus = rect(left - t, 0, t, t);
    minus = rect(left - t, t, t, t);
    ante = rect(0, 84, left - t, t);
    // Ante overlaps no bet target: the amount button stops above it.
    betButton.h = 84;
    auto = rect(rx + (right - t) / 2, sy, t, t);
    // Reserve the same full gap above and below the 8px Spin rim.
    spin = rect(rx, sy + t + gap, right, right);
    turbo = rect(rx + (right - t) / 2, sy + t + gap + right + gap, t, t);
  } else if (variant === "compact") {
    const fw = viewport.footerWidth ?? w - 72,
      read = (fw - 88 - gap * 2) / 2;
    balance = rect(0, h - t, read, t);
    win = rect(read + gap, h - t, read, t);
    bet = rect(fw - 88, h - t, 88, t);
    betButton = rect(0, 0, 88, t);
    menu = rect(w - 54, 0, t, t);
    spin = rect(w - T.compactSpin, 52, T.compactSpin, T.compactSpin);
    buy = rect(w - 54, 128, t, t);
    turbo = auto = minus = plus = ante = absent();
  } else {
    // Extra reel width is scenery, not permission to stretch the readouts.
    // Preserve target sizes and gaps while centering one compact control row.
    const groupWidth = Math.min(w, 888),
      groupX = (w - groupWidth) / 2;
    const actionWidth = t + gap + T.desktopSpin + gap + 52;
    const bx = groupWidth - actionWidth - mg - 148,
      rw = (bx - mg - 112 - mg) / 2;
    turbo = rect(groupX, 28, t, t);
    menu = rect(groupX + t + gap, 28, t, t);
    balance = rect(groupX + 112, 18, rw, 64);
    win = rect(groupX + 112 + rw + mg, 18, rw, 64);
    bet = rect(groupX + bx, 4, 148, 92);
    betButton = rect(0, 2, 104, t);
    plus = rect(104, 2, t, t);
    minus = rect(104, 46, t, t);
    ante = rect(0, 46, 104, t);
    auto = rect(groupX + groupWidth - actionWidth, 28, t, t);
    spin = rect(groupX + groupWidth - 160, 0, T.desktopSpin, T.desktopSpin);
    buy = rect(groupX + groupWidth - 52, 24, 52, 52);
  }
  const charge = rect(
    spin.x + spin.w * 0.08,
    spin.y + spin.h * (spin.w < 96 ? 0.58 : 0.64),
    spin.w * 0.84,
    variant === "compact" ? 14 : 18,
  );
  const counter = {
    ...bet,
    h: Math.min(bet.h, variant === "portrait" ? 64 : 60),
  };
  const featureTurbo =
    variant === "portrait"
      ? rect(spin.x + spin.w + gap, spin.y + (spin.h - t) / 2, t, t)
      : turbo;
  const featureMenu =
    variant === "portrait"
      ? rect(featureTurbo.x + t + gap, featureTurbo.y, t, t)
      : menu;
  return {
    ...viewport,
    balance,
    win,
    bet,
    betButton,
    minus,
    plus,
    ante,
    turbo,
    featureTurbo,
    menu,
    featureMenu,
    auto,
    spin,
    charge,
    buy,
    counter,
    drawer: { turbo: !turbo.w, auto: !auto.w, ante: !ante.w },
  };
}
export type ControlLayout = ReturnType<typeof createControlLayout>;
/** Long purchase prices use two lines inside the rim; ordinary costs stay inline. */
export function controlChargeLayout(d: ControlLayout, amount?: string) {
  const stacked =
    !!amount && (amount.length > 5 || d.spin.w < 96) && d.variant !== "compact";
  const bounds = stacked
    ? rect(
        d.spin.x + d.spin.w * 0.1,
        d.spin.y + d.spin.h * (d.spin.w < 96 ? 0.45 : 0.52),
        d.spin.w * 0.8,
        26,
      )
    : d.charge;
  return {
    ...bounds,
    stacked,
    amountSize: amount
      ? controlAmountSize(
          amount,
          bounds.w - (stacked || d.variant === "compact" ? 0 : 23),
          d.variant === "compact" || (stacked && d.spin.w < 96) ? 10 : 13,
        )
      : 12,
  };
}
export const controlPlacement = (r: ControlRect) => ({
  left: r.x,
  top: r.y,
  width: r.w,
  height: r.h,
});
/** Conservative tabular advances, checked against the shipped numeric face. */
export function controlAmountSize(
  value: string,
  width: number,
  preferred: number = T.amountSize,
) {
  const advance = [...value].reduce(
    (sum, ch) => sum + (ch === "," ? 0.26 : ch === " " ? 0.25 : 0.55),
    0,
  );
  return Math.min(
    preferred,
    Math.floor(Math.max(0, width) / Math.max(1, advance)),
  );
}
export function controlTargets(d: ControlLayout, feature = false) {
  const relative = (r: ControlRect) => ({
    ...r,
    x: d.bet.x + r.x,
    y: d.bet.y + r.y,
  });
  return Object.fromEntries(
    Object.entries({
      menu: feature ? d.featureMenu : d.menu,
      turbo: feature ? d.featureTurbo : d.turbo,
      spin: d.spin,
      ...(!feature
        ? {
            auto: d.auto,
            buy: d.buy,
            bet: relative(d.betButton),
            minus: relative(d.minus),
            plus: relative(d.plus),
            ante: relative(d.ante),
          }
        : {}),
    }).filter(([, r]) => r.w > 0),
  );
}
